import React, { useEffect, useState } from "react";
import { AdminLayout } from "../../features/admin/components/AdminLayout";
import type { AuditLogEntry } from "../../sessionServices/audit/auditLogsService";
import { listAuditLogs } from "../../sessionServices/audit/auditLogsService";
import { navigate } from "gatsby";

const ACTION_BADGE: Record<string, string> = {
  create: "bg-green-100 text-green-700",
  update: "bg-blue-100 text-blue-700",
  delete: "bg-red-100 text-red-600",
  share: "bg-purple-100 text-purple-700",
  status_change: "bg-yellow-100 text-yellow-700",
  assign_user: "bg-orange-100 text-orange-700",
  add_note: "bg-gray-100 text-gray-600",
  ai_generate: "bg-indigo-100 text-indigo-700",
};

export default function AuditPage() {
  const [logs, setLogs] = useState<AuditLogEntry[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    listAuditLogs(200)
      .then(setLogs)
      .finally(() => setLoading(false));
  }, []);

  return (
    <AdminLayout title="Audit log">
      <p className="mb-5 text-sm text-gray-500">Last 200 changes in the system.</p>
      {loading ? (
        <div className="flex items-center justify-center py-16">
          <div className="h-6 w-6 animate-spin rounded-full border-4 border-gray-300 border-t-gray-800" />
        </div>
      ) : logs.length === 0 ? (
        <div className="rounded-xl bg-white py-12 text-center ring-1 ring-gray-200">
          <p className="text-sm text-gray-500">No audit entries yet.</p>
        </div>
      ) : (
        <div className="overflow-hidden rounded-xl bg-white shadow-sm ring-1 ring-gray-200">
          <table className="min-w-full divide-y divide-gray-100">
            <thead>
              <tr className="bg-gray-50">
                <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Action</th>
                <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Entity</th>
                <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Entity ID</th>
                <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">By</th>
                <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Date</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {logs.map((log) => (
                <tr key={log.id} className="hover:bg-gray-50">
                  <td className="px-4 py-3">
                    <span className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium ${ACTION_BADGE[log.action] ?? "bg-gray-100 text-gray-600"}`}>
                      {log.action.replace("_", " ")}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-xs text-gray-600">{log.entityType}</td>
                  <td className="px-4 py-3">
                    {log.entityType === "itinerary" ? (
                      <button
                        onClick={() => navigate(`/admin/itineraries/${log.entityId}`)}
                        className="font-mono text-xs text-gray-500 underline hover:text-gray-900"
                      >
                        {log.entityId.slice(0, 10)}…
                      </button>
                    ) : (
                      <span className="font-mono text-xs text-gray-400">
                        {log.entityId.slice(0, 10)}…
                      </span>
                    )}
                  </td>
                  <td className="px-4 py-3 font-mono text-xs text-gray-400">
                    {log.performedBy.slice(0, 8)}…
                  </td>
                  <td className="px-4 py-3 text-xs text-gray-400">{formatTs(log.performedAt)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </AdminLayout>
  );
}

function formatTs(ts: unknown): string {
  try {
    return (ts as { toDate: () => Date }).toDate().toLocaleString("en-CA");
  } catch {
    return "—";
  }
}
